178	/****************************************************************************
179	 * Name: mdio_read
180	 *
181	 * Description:
182	 *   Read PHY register via MDIO.
183	 *   Source: dwmac1000.h:148-149, dwmac4.h:43-44
184	 *
185	 ****************************************************************************/
186	
187	static uint16_t mdio_read(uintptr_t gmac_base, int phy_addr, int reg)
188	{
189	  uint32_t val;
190	  int timeout = 10000;
191	
192	  val = ((phy_addr & 0x1f) << 11) | ((reg & 0x1f) << 6) | 0x1;
193	  putreg32(val, gmac_base + GMAC_MDIO_ADDR);
194	
195	  do
196	    {
197	      val = getreg32(gmac_base + GMAC_MDIO_ADDR);
198	      if (!(val & 0x1))
199	        {
200	          return getreg32(gmac_base + GMAC_MDIO_DATA) & 0xffff;
201	        }
202	
203	      up_udelay(1);
204	    }
205	  while (--timeout > 0);
206	
207	  return 0xffff;
208	}
