431	/****************************************************************************
432	 * Name: send_test_arp
433	 *
434	 * Description:
435	 *   Send a test ARP packet.
436	 *
437	 ****************************************************************************/
438	
439	static int send_test_arp(struct sg2000_eth_priv_s *priv)
440	{
441	  uint8_t pkt[64];
442	
443	  memset(pkt, 0, sizeof(pkt));
444	
445	  /* Destination: broadcast */
446	
447	  memset(pkt, 0xff, 6);
448	
449	  /* Source: self */
450	
451	  memcpy(pkt + 6, priv->mac_addr, 6);
452	
453	  /* EtherType: ARP */
454	
455	  pkt[12] = 0x08;
456	  pkt[13] = 0x06;
457	
458	  /* HTYPE: Ethernet */
459	
460	  pkt[14] = 0x00;
461	  pkt[15] = 0x01;
462	
463	  /* PTYPE: IPv4 */
464	
465	  pkt[16] = 0x08;
466	  pkt[17] = 0x00;
467	
468	  /* HLEN, PLEN */
469	
470	  pkt[18] = 6;
471	  pkt[19] = 4;
472	
473	  /* ARP Request */
474	
475	  pkt[20] = 0x00;
476	  pkt[21] = 0x01;
477	
478	  /* Sender MAC */
479	
480	  memcpy(pkt + 22, priv->mac_addr, 6);
481	
482	  /* Sender IP: 192.168.1.100 */
483	
484	  pkt[28] = 192;
485	  pkt[29] = 168;
486	  pkt[30] = 1;
487	  pkt[31] = 100;
488	
489	  /* Target IP: 192.168.1.1 */
490	
491	  pkt[38] = 192;
492	  pkt[39] = 168;
493	  pkt[40] = 1;
494	  pkt[41] = 1;
495	
496	  return send_packet(priv, pkt, sizeof(pkt));
497	}
