694	/****************************************************************************
695	 * Name: sg2000_eth_txavail
696	 *
697	 * Description:
698	 *   Called when there is data to transmit.
699	 *
700	 ****************************************************************************/
701	
702	static int sg2000_eth_txavail(struct net_driver_s *dev)
703	{
704	  struct sg2000_eth_priv_s *priv =
705	      (struct sg2000_eth_priv_s *)dev->d_private;
706	
707	  if (dev->d_len > 0)
708	    {
709	      send_packet(priv, dev->d_buf, dev->d_len);
710	      dev->d_len = 0;
711	      NETDEV_TXPACKETS(dev);
712	    }
713	
714	  return OK;
715	}
