/****************************************************************************
 * vendor/sg2000/chips/sg2000/sg2000_eth.c
 *
 * Licensed to the Apache Software Foundation (ASF) under one or more
 * contributor license agreements.  See the NOTICE file distributed with
 * this work for additional information regarding copyright ownership.  The
 * ASF licenses this file to you under the Apache License, Version 2.0 (the
 * "License"); you may not use this file except in compliance with the
 * License.  You may obtain a copy of the License at
 *
 *   http://www.apache.org/licenses/LICENSE-2.0
 *
 * Unless required by applicable law or agreed to in writing, software
 * distributed under the License is distributed on an "AS IS" BASIS, WITHOUT
 * WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.  See the
 * License for the specific language governing permissions and limitations
 * under the License.
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>
#include <nuttx/irq.h>
#include <nuttx/net/netdev.h>
#include <nuttx/net/ethernet.h>

#include "sg2000_eth.h"

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct sg2000_eth_priv_s g_eth_priv;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static inline uint32_t getreg32(uintptr_t addr)
{
  return *(volatile uint32_t *)addr;
}

static inline void putreg32(uint32_t val, uintptr_t addr)
{
  *(volatile uint32_t *)addr = val;
}

/****************************************************************************
 * Private Functions - Step 1: Register Read Test
 ****************************************************************************/

/****************************************************************************
 * Name: test_read_hw_feature
 *
 * Description:
 *   Test reading GMAC hardware feature register to verify base address.
 *
 ****************************************************************************/

static int test_read_hw_feature(uintptr_t gmac_base)
{
  uint32_t feat0 = getreg32(gmac_base + GMAC_HW_FEATURE0);

  printf("HW_FEATURE0 = 0x%08X\n", feat0);
  printf("  MII(10/100M): %s\n", (feat0 & (1 << 0)) ? "YES" : "NO");

  if (feat0 == 0x00000000 || feat0 == 0xFFFFFFFF)
    {
      printf("FAIL: Invalid value, base address wrong?\n");
      return -1;
    }

  printf("PASS\n");
  return 0;
}

/****************************************************************************
 * Private Functions - Step 2: DMA Software Reset
 ****************************************************************************/

/****************************************************************************
 * Name: dma_soft_reset
 *
 * Description:
 *   Perform DMA software reset.
 *   Source: dwmac4_lib.c:15-26
 *
 ****************************************************************************/

static int dma_soft_reset(uintptr_t gmac_base)
{
  uint32_t val;
  int timeout = 100000;

  val = getreg32(gmac_base + DMA_BUS_MODE);
  putreg32(val | DMA_SFT_RESET, gmac_base + DMA_BUS_MODE);

  do
    {
      val = getreg32(gmac_base + DMA_BUS_MODE);
      if (!(val & DMA_SFT_RESET))
        {
          printf("DMA reset PASS\n");
          return 0;
        }

      up_udelay(10);
    }
  while (--timeout > 0);

  printf("FAIL: DMA reset timeout\n");
  return -1;
}

/****************************************************************************
 * Private Functions - Step 3: EPHY Reset + MDIO Read PHY ID
 ****************************************************************************/

/****************************************************************************
 * Name: ephy_hardware_reset
 *
 * Description:
 *   Perform EPHY hardware reset sequence.
 *   Source: dwmac-cvitek.c:46-117
 *
 ****************************************************************************/

static void ephy_hardware_reset(uintptr_t phy_base, uintptr_t phy_top)
{
  /* Select APB interface */

  putreg32(0x0001, phy_top + 0x4);

  /* Release shutdown */

  putreg32(0x0900, phy_top);

  /* Release dig_rst_n */

  putreg32(0x0904, phy_top);

  /* Switch to Page 5 */

  putreg32(0x0500, phy_base + 0x7c);

  /* ANA_PD */

  putreg32(0x0c00, phy_base + 0x40);

  /* ANA_EN */

  putreg32(0x0c7e, phy_base + 0x40);
  up_mdelay(1);

  /* Release ana_rst_n */

  putreg32(0x0906, phy_top);
  putreg32(0x0500, phy_base + 0x7c);

  /* Set PHY ID */

  putreg32(0x0043, phy_base + 0x08);  /* PHY_ID_HIGH */
  putreg32(0x5649, phy_base + 0x0c);  /* PHY_ID_LOW */

  /* Switch back to MDIO control */

  putreg32(0x0000, phy_top + 0x4);
  up_mdelay(10);
}

/****************************************************************************
 * Name: mdio_read
 *
 * Description:
 *   Read PHY register via MDIO.
 *   Source: dwmac1000.h:148-149, dwmac4.h:43-44
 *
 ****************************************************************************/

static uint16_t mdio_read(uintptr_t gmac_base, int phy_addr, int reg)
{
  uint32_t val;
  int timeout = 10000;

  val = ((phy_addr & 0x1f) << 11) | ((reg & 0x1f) << 6) | 0x1;
  putreg32(val, gmac_base + GMAC_MDIO_ADDR);

  do
    {
      val = getreg32(gmac_base + GMAC_MDIO_ADDR);
      if (!(val & 0x1))
        {
          return getreg32(gmac_base + GMAC_MDIO_DATA) & 0xffff;
        }

      up_udelay(1);
    }
  while (--timeout > 0);

  return 0xffff;
}

/****************************************************************************
 * Private Functions - Step 4: Allocate DMA Descriptor Rings
 ****************************************************************************/

/****************************************************************************
 * Name: alloc_dma
 *
 * Description:
 *   Allocate DMA descriptor rings and buffers.
 *
 ****************************************************************************/

static int alloc_dma(struct sg2000_eth_priv_s *priv)
{
  int i;

  priv->tx_desc = kmm_memalign(16, TX_RING_SIZE *
                                sizeof(struct sg2000_dma_desc_s));
  priv->rx_desc = kmm_memalign(16, RX_RING_SIZE *
                                sizeof(struct sg2000_dma_desc_s));

  if (!priv->tx_desc || !priv->rx_desc)
    {
      return -ENOMEM;
    }

  memset(priv->tx_desc, 0, TX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
  memset(priv->rx_desc, 0, RX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));

  /* MMU-less: virtual address = physical address */

  priv->tx_desc_phys = (uint32_t)(uintptr_t)priv->tx_desc;
  priv->rx_desc_phys = (uint32_t)(uintptr_t)priv->rx_desc;

  for (i = 0; i < TX_RING_SIZE; i++)
    {
      priv->tx_buf[i] = kmm_memalign(4, TX_BUF_SIZE);
    }

  for (i = 0; i < RX_RING_SIZE; i++)
    {
      priv->rx_buf[i] = kmm_memalign(4, RX_BUF_SIZE);
    }

  return 0;
}

/****************************************************************************
 * Name: init_desc_and_dma
 *
 * Description:
 *   Initialize descriptor rings and write DMA registers.
 *
 ****************************************************************************/

static void init_desc_and_dma(struct sg2000_eth_priv_s *priv)
{
  uintptr_t base = priv->gmac_base;
  uintptr_t dma = base + DMA_CHAN_BASE;
  int i;

  /* TX descriptors: clear all */

  for (i = 0; i < TX_RING_SIZE; i++)
    {
      priv->tx_desc[i].des0 = 0;
      priv->tx_desc[i].des2 = (uint32_t)(uintptr_t)priv->tx_buf[i];
    }

  /* RX descriptors: set OWN=1 (DMA can write) */

  for (i = 0; i < RX_RING_SIZE; i++)
    {
      priv->rx_desc[i].des0 = DESC_OWN;
      priv->rx_desc[i].des1 = RX_BUF_SIZE;
      priv->rx_desc[i].des2 = (uint32_t)(uintptr_t)priv->rx_buf[i];
    }

  priv->tx_cur = 0;
  priv->tx_dirty = 0;
  priv->rx_cur = 0;

  /* Write DMA registers */

  putreg32(DMA_SYS_DEFAULT, base + DMA_SYS_BUS_MODE);
  putreg32(TX_RING_SIZE - 1, dma + DMA_CHAN_TX_RING_LEN);
  putreg32(RX_RING_SIZE - 1, dma + DMA_CHAN_RX_RING_LEN);
  putreg32(priv->tx_desc_phys, dma + DMA_CHAN_TX_BASE_ADDR);
  putreg32(priv->rx_desc_phys, dma + DMA_CHAN_RX_BASE_ADDR);
  putreg32(DMA_INTR_DEFAULT_MASK, dma + DMA_CHAN_INTR_ENA);
}

/****************************************************************************
 * Private Functions - Step 5: Configure MAC + Start DMA + Send Test Packet
 ****************************************************************************/

/****************************************************************************
 * Name: set_mac_addr
 *
 * Description:
 *   Set MAC address in hardware.
 *   Source: dwmac4_lib.c:187-201
 *
 ****************************************************************************/

static void set_mac_addr(uintptr_t gmac_base, const uint8_t *mac)
{
  uint32_t hi;
  uint32_t lo;

  hi = (mac[5] << 8) | mac[4] | GMAC_HI_REG_AE;
  lo = (mac[3] << 24) | (mac[2] << 16) | (mac[1] << 8) | mac[0];

  putreg32(hi, gmac_base + GMAC_ADDR_HIGH(0));
  putreg32(lo, gmac_base + GMAC_ADDR_LOW(0));
}

/****************************************************************************
 * Name: start_mac_and_dma
 *
 * Description:
 *   Start MAC and DMA.
 *   Source: dwmac4_core.c:48 + dwmac4_lib.c:38-73
 *
 ****************************************************************************/

static void start_mac_and_dma(uintptr_t gmac_base)
{
  uintptr_t dma = gmac_base + DMA_CHAN_BASE;
  uint32_t v;

  v = GMAC_CORE_INIT | GMAC_CONFIG_FES | GMAC_CONFIG_DM;
  putreg32(v, gmac_base + GMAC_CONFIG);

  putreg32(GMAC_FILTER_HMC | GMAC_FILTER_PM,
           gmac_base + GMAC_PACKET_FILTER);

  putreg32(GMAC_INT_DEFAULT, gmac_base + GMAC_INT_EN);

  /* Enable TX and RX */

  v = getreg32(gmac_base + GMAC_CONFIG);
  putreg32(v | GMAC_CONFIG_TE | GMAC_CONFIG_RE, gmac_base + GMAC_CONFIG);

  /* Start TX DMA */

  v = getreg32(dma + DMA_CHAN_TX_CONTROL);
  putreg32(v | DMA_TX_ST, dma + DMA_CHAN_TX_CONTROL);

  /* Start RX DMA */

  v = getreg32(dma + DMA_CHAN_RX_CONTROL);
  putreg32(v | DMA_RX_SR, dma + DMA_CHAN_RX_CONTROL);
}

/****************************************************************************
 * Name: tx_doorbell
 *
 * Description:
 *   Update TX Tail Pointer (doorbell).
 *   Source: dwmac4_lib.c:33-36
 *
 ****************************************************************************/

static void tx_doorbell(struct sg2000_eth_priv_s *priv)
{
  uint32_t tail = priv->tx_desc_phys +
                  priv->tx_cur * sizeof(struct sg2000_dma_desc_s);

  putreg32(tail, priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_END_ADDR);
}

/****************************************************************************
 * Name: rx_doorbell
 *
 * Description:
 *   Update RX Tail Pointer (doorbell).
 *   Source: dwmac4_lib.c:28-31
 *
 ****************************************************************************/

static void rx_doorbell(struct sg2000_eth_priv_s *priv)
{
  uint32_t tail = priv->rx_desc_phys +
                  priv->rx_cur * sizeof(struct sg2000_dma_desc_s);

  putreg32(tail, priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_END_ADDR);
}

/****************************************************************************
 * Name: send_packet
 *
 * Description:
 *   Send a packet via DMA.
 *
 ****************************************************************************/

static int send_packet(struct sg2000_eth_priv_s *priv,
                       const uint8_t *data, int len)
{
  unsigned int idx = priv->tx_cur;
  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];

  if (desc->des0 & DESC_OWN)
    {
      printf("TX ring full\n");
      return -EBUSY;
    }

  memcpy(priv->tx_buf[idx], data, len);

  desc->des2 = (uint32_t)(uintptr_t)priv->tx_buf[idx];
  desc->des1 = len;
  desc->des0 = DESC_OWN | TX_DESC_FS | TX_DESC_LS | TX_DESC_IC | len;

  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);

  tx_doorbell(priv);
  return 0;
}

/****************************************************************************
 * Name: send_test_arp
 *
 * Description:
 *   Send a test ARP packet.
 *
 ****************************************************************************/

static int send_test_arp(struct sg2000_eth_priv_s *priv)
{
  uint8_t pkt[64];

  memset(pkt, 0, sizeof(pkt));

  /* Destination: broadcast */

  memset(pkt, 0xff, 6);

  /* Source: self */

  memcpy(pkt + 6, priv->mac_addr, 6);

  /* EtherType: ARP */

  pkt[12] = 0x08;
  pkt[13] = 0x06;

  /* HTYPE: Ethernet */

  pkt[14] = 0x00;
  pkt[15] = 0x01;

  /* PTYPE: IPv4 */

  pkt[16] = 0x08;
  pkt[17] = 0x00;

  /* HLEN, PLEN */

  pkt[18] = 6;
  pkt[19] = 4;

  /* ARP Request */

  pkt[20] = 0x00;
  pkt[21] = 0x01;

  /* Sender MAC */

  memcpy(pkt + 22, priv->mac_addr, 6);

  /* Sender IP: 192.168.1.100 */

  pkt[28] = 192;
  pkt[29] = 168;
  pkt[30] = 1;
  pkt[31] = 100;

  /* Target IP: 192.168.1.1 */

  pkt[38] = 192;
  pkt[39] = 168;
  pkt[40] = 1;
  pkt[41] = 1;

  return send_packet(priv, pkt, sizeof(pkt));
}

/****************************************************************************
 * Private Functions - Step 6: ISR + RX Receive
 ****************************************************************************/

/****************************************************************************
 * Name: sg2000_eth_isr
 *
 * Description:
 *   Interrupt service routine.
 *   Source: dwmac4_lib.c:141-184
 *
 ****************************************************************************/

static int sg2000_eth_isr(int irq, void *context, void *arg)
{
  struct sg2000_eth_priv_s *priv = (struct sg2000_eth_priv_s *)arg;
  uintptr_t base = priv->gmac_base;
  uintptr_t dma = base + DMA_CHAN_BASE;
  uint32_t status;
  uint32_t intr_en;
  uint32_t mac;

  mac = getreg32(base + GMAC_INT_STATUS);
  if (mac)
    {
      putreg32(mac, base + GMAC_INT_STATUS);
    }

  intr_en = getreg32(dma + DMA_CHAN_INTR_ENA);
  status = getreg32(dma + DMA_CHAN_STATUS) & intr_en;

  if (!status)
    {
      return OK;
    }

  /* W1C clear */

  putreg32(status, dma + DMA_CHAN_STATUS);

  if (status & DMA_STATUS_NIS)
    {
      if (status & DMA_STATUS_RI)
        {
          netdev_rx_ready(&priv->dev);
        }

      if (status & DMA_STATUS_TI)
        {
          /* TX complete */
        }
    }

  if (status & DMA_STATUS_AIS)
    {
      printf("!! DMA Abnormal: 0x%08X\n", status);

      if (status & DMA_STATUS_RBU)
        {
          printf("   RX Buf Unavailable\n");
        }

      if (status & DMA_STATUS_TPS)
        {
          printf("   TX Stopped\n");
        }

      if (status & DMA_STATUS_FBE)
        {
          printf("   Fatal Bus Error\n");
        }
    }

  return OK;
}

/****************************************************************************
 * Name: sg2000_eth_rx
 *
 * Description:
 *   Receive a packet from DMA ring.
 *
 ****************************************************************************/

static int sg2000_eth_rx(struct sg2000_eth_priv_s *priv)
{
  struct sg2000_dma_desc_s *desc = &priv->rx_desc[priv->rx_cur];
  uint32_t status;
  int len;

  if (desc->des0 & DESC_OWN)
    {
      return 0;  /* DMA still owns it */
    }

  status = desc->des0;

  if (status & RX_DESC_ES)
    {
      goto refill;  /* Error packet, discard */
    }

  len = ((status >> RX_DESC_FL_SHIFT) & RX_DESC_FL_MASK) - 4;  /* Remove FCS */

  if (len > CONFIG_NET_ETH_PKTSIZE)
    {
      goto refill;
    }

  memcpy(priv->dev.d_buf, priv->rx_buf[priv->rx_cur], len);
  priv->dev.d_len = len;

refill:

  /* Return descriptor to DMA */

  desc->des0 = DESC_OWN;
  desc->des1 = RX_BUF_SIZE;

  priv->rx_cur = (priv->rx_cur + 1) & (RX_RING_SIZE - 1);

  rx_doorbell(priv);

  return (priv->dev.d_len > 0) ? 1 : 0;
}

/****************************************************************************
 * Private Functions - Step 7: NuttX Netdev Callbacks
 ****************************************************************************/

/****************************************************************************
 * Name: sg2000_eth_ifup
 *
 * Description:
 *   Called when the network interface is brought up.
 *
 ****************************************************************************/

static int sg2000_eth_ifup(struct net_driver_s *dev)
{
  struct sg2000_eth_priv_s *priv =
      (struct sg2000_eth_priv_s *)dev->d_private;

  ephy_hardware_reset(priv->phy_base, priv->phy_top);
  dma_soft_reset(priv->gmac_base);
  init_desc_and_dma(priv);
  set_mac_addr(priv->gmac_base, priv->mac_addr);
  start_mac_and_dma(priv->gmac_base);
  rx_doorbell(priv);

  up_enable_irq(priv->irq);
  netdev_carrier_on(dev);

  return OK;
}

/****************************************************************************
 * Name: sg2000_eth_ifdown
 *
 * Description:
 *   Called when the network interface is brought down.
 *
 ****************************************************************************/

static int sg2000_eth_ifdown(struct net_driver_s *dev)
{
  struct sg2000_eth_priv_s *priv =
      (struct sg2000_eth_priv_s *)dev->d_private;
  uint32_t v;

  up_disable_irq(priv->irq);

  /* Stop TX DMA */

  v = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_CONTROL);
  putreg32(v & ~DMA_TX_ST,
           priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_CONTROL);

  /* Stop RX DMA */

  v = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_CONTROL);
  putreg32(v & ~DMA_RX_SR,
           priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_CONTROL);

  /* Disable MAC TX/RX */

  v = getreg32(priv->gmac_base + GMAC_CONFIG);
  putreg32(v & ~(GMAC_CONFIG_TE | GMAC_CONFIG_RE),
           priv->gmac_base + GMAC_CONFIG);

  netdev_carrier_off(dev);

  return OK;
}

/****************************************************************************
 * Name: sg2000_eth_txavail
 *
 * Description:
 *   Called when there is data to transmit.
 *
 ****************************************************************************/

static int sg2000_eth_txavail(struct net_driver_s *dev)
{
  struct sg2000_eth_priv_s *priv =
      (struct sg2000_eth_priv_s *)dev->d_private;

  if (dev->d_len > 0)
    {
      send_packet(priv, dev->d_buf, dev->d_len);
      dev->d_len = 0;
      NETDEV_TXPACKETS(dev);
    }

  return OK;
}

/****************************************************************************
 * Name: sg2000_eth_rmac
 *
 * Description:
 *   Called to receive packets (poll mode).
 *
 ****************************************************************************/

static int sg2000_eth_rmac(struct net_driver_s *dev)
{
  struct sg2000_eth_priv_s *priv =
      (struct sg2000_eth_priv_s *)dev->d_private;

  if (sg2000_eth_rx(priv))
    {
      NETDEV_RXPACKETS(dev);
    }

  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: sg2000_eth_initialize
 *
 * Description:
 *   Initialize the SG2000 ethernet driver.
 *
 ****************************************************************************/

int sg2000_eth_initialize(void)
{
  struct sg2000_eth_priv_s *priv = &g_eth_priv;
  int ret;
  uint16_t id1;
  uint16_t id2;
  uint32_t phy_id;
  uint32_t r1;
  uint32_t r2;

  memset(priv, 0, sizeof(*priv));
  priv->gmac_base = SG2000_GMAC_BASE;
  priv->phy_base = SG2000_EPHY_BASE;
  priv->phy_top = SG2000_EPHY_TOP;

  /* Set test MAC address */

  priv->mac_addr[0] = 0x02;
  priv->mac_addr[1] = 0x00;
  priv->mac_addr[2] = 0x00;
  priv->mac_addr[3] = 0x00;
  priv->mac_addr[4] = 0x00;
  priv->mac_addr[5] = 0x01;

  /* Step 1: Verify register readability */

  ret = test_read_hw_feature(priv->gmac_base);
  if (ret < 0)
    {
      return ret;
    }

  /* Step 2: DMA software reset */

  ret = dma_soft_reset(priv->gmac_base);
  if (ret < 0)
    {
      return ret;
    }

  /* Step 3: EPHY reset + MDIO read PHY ID */

  ephy_hardware_reset(priv->phy_base, priv->phy_top);

  id1 = mdio_read(priv->gmac_base, 0, 2);
  id2 = mdio_read(priv->gmac_base, 0, 3);
  phy_id = (id1 << 16) | id2;

  printf("PHY ID = 0x%08X (expect 0x00435649)\n", phy_id);

  if (phy_id == CVITEK_PHY_ID)
    {
      printf("PHY ID PASS\n");
    }
  else if (phy_id == 0xffffffff)
    {
      printf("FAIL: PHY not responding\n");
      return -1;
    }
  else
    {
      printf("FAIL: Unexpected PHY ID\n");
      return -1;
    }

  /* Step 4: Allocate DMA descriptor rings + write DMA registers */

  ret = alloc_dma(priv);
  if (ret < 0)
    {
      printf("FAIL: alloc_dma\n");
      return ret;
    }

  init_desc_and_dma(priv);

  /* Readback verification */

  r1 = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_BASE_ADDR);
  r2 = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_RING_LEN);

  printf("Readback TX_BASE: 0x%08X (expect 0x%08X) %s\n",
         r1, priv->tx_desc_phys,
         r1 == priv->tx_desc_phys ? "OK" : "FAIL");
  printf("Readback TX_LEN:  %d (expect %d) %s\n",
         r2, TX_RING_SIZE - 1,
         r2 == (TX_RING_SIZE - 1) ? "OK" : "FAIL");

  if (r1 != priv->tx_desc_phys || r2 != (TX_RING_SIZE - 1))
    {
      return -1;
    }

  /* Step 5: Configure MAC + start DMA + send test packet */

  set_mac_addr(priv->gmac_base, priv->mac_addr);
  start_mac_and_dma(priv->gmac_base);
  rx_doorbell(priv);

  printf("Sending test ARP packet...\n");
  ret = send_test_arp(priv);
  if (ret < 0)
    {
      printf("FAIL: send_test_arp\n");
      return ret;
    }

  printf("Test ARP sent. Check with tcpdump on PC.\n");

  /* Step 6: Register ISR */

  priv->irq = SG2000_IRQ_GMAC;
  irq_attach(priv->irq, sg2000_eth_isr, priv);
  up_enable_irq(priv->irq);

  printf("IRQ %d enabled. Waiting for packets...\n", priv->irq);

  /* Step 7: Register netdev */

  priv->dev.d_buf = kmm_zalloc(CONFIG_NET_ETH_PKTSIZE);
  if (!priv->dev.d_buf)
    {
      printf("FAIL: alloc d_buf\n");
      return -ENOMEM;
    }

  priv->dev.d_ifup = sg2000_eth_ifup;
  priv->dev.d_ifdown = sg2000_eth_ifdown;
  priv->dev.d_txavail = sg2000_eth_txavail;
  priv->dev.d_rmac = sg2000_eth_rmac;
  priv->dev.d_private = priv;

  ret = netdev_register(&priv->dev, NET_LL_ETHERNET);
  if (ret < 0)
    {
      printf("FAIL: netdev_register: %d\n", ret);
      return ret;
    }

  printf("SG2000 Ethernet driver registered as eth0\n");

  return OK;
}

