#define SG2000_GMAC_BASE          0x04070000

/****************************************************************************
 * Public Types
 ****************************************************************************/

/* DWMAC4 Enhanced Descriptor (16 bytes) */

struct sg2000_dma_desc_s
{
  uint32_t des0;  /* Status / OWN */
  uint32_t des1;  /* Buffer size */
  uint32_t des2;  /* Buffer address */
  uint32_t des3;  /* Next descriptor / reserved */
};

/* Driver private data */

struct sg2000_eth_priv_s
{
  struct net_driver_s dev;          /* NuttX netdev (must be first) */

  uintptr_t gmac_base;              /* GMAC register base */
  uintptr_t phy_base;               /* EPHY register base */
  uintptr_t phy_top;                /* EPHY Top register base */

  /* DMA descriptors */

  struct sg2000_dma_desc_s *tx_desc;
  struct sg2000_dma_desc_s *rx_desc;
  uint8_t *tx_buf[TX_RING_SIZE];
  uint8_t *rx_buf[RX_RING_SIZE];

  uint32_t tx_desc_phys;            /* TX descriptor physical address */
  uint32_t rx_desc_phys;            /* RX descriptor physical address */

  unsigned int tx_cur;              /* Current TX position */
  unsigned int tx_dirty;            /* TX clean position */
  unsigned int rx_cur;              /* Current RX position */

  uint8_t mac_addr[6];
  int irq;
};

/****************************************************************************
 * Public Function Prototypes
 ****************************************************************************/

